-- GARDA INFLASI - Registri Model & Proyeksi Harga Demo (prediksi)
--
-- Padanan seeder Go lama internal/prediksi/seeder. Semua baris bersumber 'DEMO': bukan keluaran model sungguhan, dan
-- hanya ada di lapis demo. Bentuknya meniru mockXai di apps/web/src/lib/api/mock.ts supaya halaman prediksi tampil sama
-- dengan mode mock. Produksi tidak di-seed: registri dan proyeksi diisi pipeline ML (slice 11-B), jadi model_registry
-- dan prediksi_harga kosong sesudah `seed reference admin`.
--
-- Prasyarat: reference/01_master.sql (komoditas dan kabupaten).
--
-- Tanggal relatif terhadap hari ini UTC (hari dasar): model produksi dilatih 7 hari lalu, kandidat 1 hari lalu; tanggal
-- target proyeksi = hari dasar + horizon. Menjalankan ulang di hari lain menggeser tanggal tersebut, bukan menambah baris.
--
-- Idempoten menurut kolom kode (ID lama; kunci unik uq_model_registry_kode dan uq_prediksi_harga_kode). ID BIGINT
-- selalu diberikan basis data (tidak ditulis eksplisit, jadi urutan identity tidak perlu disetel ulang) dan proyeksi
-- ditautkan ke model lewat (komoditas_kode, versi). Status model tidak ikut diperbarui saat seed ulang, supaya promosi
-- dan pengarsipan lewat API tidak dibatalkan (indeks unik hanya mengizinkan satu model PRODUKSI per komoditas); baris
-- yang bukan DEMO tidak pernah disentuh.

-- =====================================================================
-- Tabel: model_registry (28 baris: model produksi v2.3.1 dan kandidat v2.4.0-rc1 per komoditas)
-- =====================================================================
INSERT INTO model_registry (kode, komoditas_kode, nama, versi, algorithm, status, mape, drift, dilatih_pada, metrics, feature_importance, sumber, catatan)
SELECT
  'MDL-' || v.komoditas_kode || '-' || v.versi,
  v.komoditas_kode,
  'Ensemble LightGBM + SARIMAX',
  v.versi,
  'Ensemble LightGBM + SARIMAX',
  v.status::status_model,
  v.mape,
  v.drift,
  (h.hari - v.hari_lalu)::timestamp AT TIME ZONE 'UTC',
  '{}'::jsonb,
  '[]'::jsonb,
  'DEMO',
  'Data contoh seeder, bukan keluaran model sungguhan.'
FROM (VALUES
  ('BRS-MED', 'v2.3.1', 'PRODUKSI', 2.2, 0, 7),
  ('BRS-MED', 'v2.4.0-rc1', 'KANDIDAT', 2, 0, 1),
  ('BRS-PRM', 'v2.3.1', 'PRODUKSI', 2.2, 0.03, 7),
  ('BRS-PRM', 'v2.4.0-rc1', 'KANDIDAT', 2, 0, 1),
  ('BWM', 'v2.3.1', 'PRODUKSI', 5.3, 0.12, 7),
  ('BWM', 'v2.4.0-rc1', 'KANDIDAT', 4.9, 0, 1),
  ('BWP', 'v2.3.1', 'PRODUKSI', 3.3, 0, 7),
  ('BWP', 'v2.4.0-rc1', 'KANDIDAT', 3.1, 0, 1),
  ('CBM-KRT', 'v2.3.1', 'PRODUKSI', 7.6, 0.06, 7),
  ('CBM-KRT', 'v2.4.0-rc1', 'KANDIDAT', 7.1, 0, 1),
  ('CBR-RWT', 'v2.3.1', 'PRODUKSI', 8.3, 0.09, 7),
  ('CBR-RWT', 'v2.4.0-rc1', 'KANDIDAT', 7.7, 0, 1),
  ('DAG-AYM', 'v2.3.1', 'PRODUKSI', 3.7, 0.06, 7),
  ('DAG-AYM', 'v2.4.0-rc1', 'KANDIDAT', 3.4, 0, 1),
  ('DAG-SPI', 'v2.3.1', 'PRODUKSI', 2, 0.09, 7),
  ('DAG-SPI', 'v2.4.0-rc1', 'KANDIDAT', 1.9, 0, 1),
  ('GLA', 'v2.3.1', 'PRODUKSI', 2, 0.03, 7),
  ('GLA', 'v2.4.0-rc1', 'KANDIDAT', 1.9, 0, 1),
  ('IKN-TGK', 'v2.3.1', 'PRODUKSI', 5.8, 0.12, 7),
  ('IKN-TGK', 'v2.4.0-rc1', 'KANDIDAT', 5.4, 0, 1),
  ('KTG', 'v2.3.1', 'PRODUKSI', 4.2, 0.06, 7),
  ('KTG', 'v2.4.0-rc1', 'KANDIDAT', 3.9, 0, 1),
  ('MYK', 'v2.3.1', 'PRODUKSI', 2, 0, 7),
  ('MYK', 'v2.4.0-rc1', 'KANDIDAT', 1.9, 0, 1),
  ('TLR', 'v2.3.1', 'PRODUKSI', 2.9, 0.03, 7),
  ('TLR', 'v2.4.0-rc1', 'KANDIDAT', 2.7, 0, 1),
  ('TMT', 'v2.3.1', 'PRODUKSI', 6.9, 0.09, 7),
  ('TMT', 'v2.4.0-rc1', 'KANDIDAT', 6.4, 0, 1)
) AS v(komoditas_kode, versi, status, mape, drift, hari_lalu)
CROSS JOIN (SELECT (now() AT TIME ZONE 'UTC')::date AS hari) h
ON CONFLICT (kode) DO UPDATE
  SET nama = EXCLUDED.nama, algorithm = EXCLUDED.algorithm, mape = EXCLUDED.mape, drift = EXCLUDED.drift,
      dilatih_pada = EXCLUDED.dilatih_pada, sumber = EXCLUDED.sumber, catatan = EXCLUDED.catatan
  WHERE model_registry.sumber = 'DEMO';

