CROSS JOIN (SELECT (now() AT TIME ZONE 'UTC')::date AS hari) h
JOIN model_registry m ON m.komoditas_kode = v.komoditas_kode AND m.versi = 'v2.3.1'
ON CONFLICT (kode) DO UPDATE
  SET tanggal_target = EXCLUDED.tanggal_target, nilai = EXCLUDED.nilai, bawah = EXCLUDED.bawah, atas = EXCLUDED.atas,
      harga_dasar = EXCLUDED.harga_dasar, faktor = EXCLUDED.faktor, sumber = EXCLUDED.sumber,
      dibuat_pada = EXCLUDED.dibuat_pada, model_id = EXCLUDED.model_id, model_versi = EXCLUDED.model_versi
  WHERE prediksi_harga.sumber = 'DEMO';
